LESSONS = [
    {"title":"Candlestick basics","eli10":"Each candle is a tiny summary of what price did during a chosen time period. The body shows where it opened and closed; the wicks show the highest and lowest prices reached.","look_for":["Open and close","High and low wicks","Whether the candle closed up or down"],"mistake":"Treating one candle as proof of what price will do next."},
    {"title":"Support and resistance","eli10":"Think of these as areas where price has previously struggled to move through. They are zones to study, not invisible walls.","look_for":["Repeated reactions around a similar area","How price behaves when it returns","Whether a level has been cleanly crossed"],"mistake":"Assuming a level must hold just because it held before."},
    {"title":"Trend structure","eli10":"An uptrend often makes higher highs and higher lows. A downtrend often makes lower highs and lower lows. Sideways markets move between boundaries.","look_for":["Recent swing highs","Recent swing lows","Whether swings are rising, falling, or staying in a range"],"mistake":"Calling a trend from only one or two candles."},
    {"title":"EMA 20, 50 and 200","eli10":"An EMA is a moving average that gives more weight to recent prices. Different lengths help you compare shorter and longer views of the same chart.","look_for":["Where price sits relative to each average","Whether averages slope up, down, or sideways","How the averages relate to each other"],"mistake":"Treating an EMA cross as a guaranteed signal."},
    {"title":"Pullbacks","eli10":"A pullback is a temporary move against the direction of a broader trend. It may continue the trend, or it may become something bigger.","look_for":["The prior trend structure","Whether important swing points remain intact","How the move develops over completed candles"],"mistake":"Assuming every dip in an uptrend is a buying opportunity."},
    {"title":"Reversals","eli10":"A reversal means the market's previous direction may be changing. It takes more evidence than a single opposite-coloured candle.","look_for":["A change in swing structure","Failed attempts to continue the old trend","Confirmation across more than one observation"],"mistake":"Declaring a reversal too early."},
    {"title":"Breakouts and ranges","eli10":"A range is an area where price moves sideways. A breakout is movement beyond the range boundary. Some breakouts fail and return inside.","look_for":["Clear range boundaries","A candle closing beyond the boundary","Whether price stays outside or returns"],"mistake":"Assuming every move beyond a boundary will continue."},
    {"title":"Momentum and volatility","eli10":"Momentum tools describe the pace of price movement. Volatility describes how much price has been moving. Neither tells the future with certainty.","look_for":["RSI or Stochastic changes","ATR changes over time","Whether price movement is unusually quiet or active"],"mistake":"Using overbought or oversold readings as automatic reversal calls."},
    {"title":"Risk and percentage maths","eli10":"A percentage shows how large a change is compared with the starting amount. Drawdown describes a decline from a previous high. Learn the maths with fictional numbers first.","look_for":["Starting value and ending value","Percentage change","How a series of losses affects a balance"],"mistake":"Thinking a high win rate alone proves a strategy is good."},
    {"title":"Putting the picture together","eli10":"Good chart reading means describing the bigger context, the current structure, and what is still uncertain. It is okay to conclude that the chart is unclear.","look_for":["Higher timeframe context","Current swing structure","Volatility and indicator context","What evidence would change your interpretation"],"mistake":"Forcing a conclusion when the evidence is mixed."}
]

QUIZ = {
    "What do candle wicks show?": {"choices":["The highest and lowest prices during the candle","Only the closing price","The broker's spread"],"answer":"The highest and lowest prices during the candle","why":"The upper and lower wicks mark the high and low reached during that candle."},
    "What is a pullback?": {"choices":["A temporary move against a broader trend","A guaranteed reversal","A type of moving average"],"answer":"A temporary move against a broader trend","why":"A pullback moves against the broader direction, but does not by itself prove the trend has changed."},
    "What does ATR describe?": {"choices":["Historical volatility","The next price target","Whether to buy or sell"],"answer":"Historical volatility","why":"ATR estimates recent range/volatility. It does not predict direction."},
    "What is the safest conclusion when evidence conflicts?": {"choices":["The chart is unclear; gather more observations","Pick a direction anyway","Use a bigger position"],"answer":"The chart is unclear; gather more observations","why":"Recognizing uncertainty is an important analysis skill."}
}
